insert into public.legal_texts
  (id, code, type, domain, domain_icon, status, status_label, verification_status, title, summary, hashtags, articles_count, articles, replaced_by, source_url)
values
  ('const-2010', 'C-2010', 'Constitution', 'Droit Constitutionnel', 'fa-landmark', 'en_vigueur', 'En vigueur', 'unverified', 'Constitution de la IVe République de Madagascar', 'Texte fondamental régissant les institutions républicaines, la démocratie, les droits fondamentaux et l''organisation de l''État.', ARRAY['#Souveraineté', '#Libertés', '#Institutions', '#Démocratie']::text[], 4, '[{"number":"Article 1","text":"Le peuple malagasy constitue une Nation organisée en État souverain, unitaire, républicain et démocratique. La souveraineté appartient au peuple qui l''exerce par ses représentants ou par la voie du référendum. Souveraineté","references":[],"definitions":[{"term":"Souveraineté","definition":"Principe fondamental selon lequel le pouvoir politique suprême réside dans la Nation malagasy et ne peut être usurpé par un individu ou une faction."}]},{"number":"Article 6","text":"La loi est l''expression de la volonté générale. Elle est la même pour tous, qu''elle protège, qu''elle punisse ou qu''elle oblige. Les relations de travail individuelles et collectives sont régies par la Loi n° 2003-044 portant Code du Travail .","references":[{"law_id":"loi-travail-2003","article":"Article 11","label":"Loi n° 2003-044 portant Code du Travail"}],"definitions":[]},{"number":"Article 34","text":"L''État garantit le droit de propriété individuelle ou collective. Nul ne peut en être privé si ce n''est pour cause d''utilité publique dûment constatée. Se référer également à la Loi n° 2008-014 sur le Domaine Privé de l’État .","references":[{"law_id":"loi-foncier-2008","article":"Article 15","label":"Loi n° 2008-014 sur le Domaine Privé de l’État"}],"definitions":[]},{"number":"Article 95","text":"La Loi Organique fixe les règles relatives à l''élection du Président de la République et du Parlement. Voir la Loi Organique n° 2018-008 .","references":[{"law_id":"loi-org-elections-2018","article":"Article 1","label":"Loi Organique n° 2018-008"}],"definitions":[]}]'::jsonb, null, null),
  ('loi-org-elections-2018', 'Loi Organique n° 2018-008', 'Loi Organique', 'Droit Constitutionnel', 'fa-landmark', 'en_vigueur', 'En vigueur', 'unverified', 'Loi Organique n° 2018-008 relative au Régime Général des Élections et Référendums', 'Fixe le cadre électoral global, le rôle de la CENI, l''établissement des listes électorales et la transparence du scrutin.', ARRAY['#Élections', '#CENI', '#Référendum', '#Suffrage']::text[], 2, '[{"number":"Article 1","text":"La présente Loi Organique fixe les principes généraux applicables à l''organisation de l''ensemble des opérations électorales et référendaires en République de Madagascar conformément à l'' Article 95 de la Constitution .","references":[{"law_id":"const-2010","article":"Article 95","label":"Article 95 de la Constitution"}],"definitions":[]},{"number":"Article 12","text":"Sont électeurs tous les citoyens malagasy des deux sexes, âgés de 18 ans accomplis au jour du scrutin, jouissant de leurs droits civils et politiques.","references":[],"definitions":[]}]'::jsonb, null, null),
  ('loi-travail-2003', 'Loi n° 2003-044', 'Loi Ordinaire', 'Droit du Travail', 'fa-briefcase', 'consolide', 'Texte Consolidé', 'unverified', 'Loi n° 2003-044 portant Code du Travail à Madagascar', 'Régit l''ensemble des relations de travail entre employeurs et salariés, la durée du travail, les préavis et les congés payés.', ARRAY['#Licenciement', '#Chômage technique', '#Salaires', '#Congés']::text[], 3, '[{"number":"Article 11","text":"Le contrat de travail à durée déterminée (CDD) ne peut avoir pour objet ni pour effet de pourvoir durablement à un emploi lié à l''activité normale et permanente de l''entreprise.","references":[],"definitions":[]},{"number":"Article 42","text":"En cas de rupture du contrat de travail, un préavis de licenciement doit être respecté. La durée minimale du préavis dépend de la catégorie professionnelle. Voir aussi le Décret d''application n° 2004-1013 .","references":[{"law_id":"decret-preavis-2004","article":"Article 1","label":"Décret d''application n° 2004-1013"}],"definitions":[{"term":"Préavis de licenciement","definition":"Délai légal d exécution du travail ou de compensation financière accordé avant la prise d effet définitive de la résiliation du contrat."}]},{"number":"Article 55","text":"Le salarié a droit à un congé payé à la charge de l''employeur à raison de 2,5 jours à compter de chaque mois de travail effectif.","references":[],"definitions":[]}]'::jsonb, null, null),
  ('decret-preavis-2004', 'Décret n° 2004-1013', 'Décret', 'Droit du Travail', 'fa-briefcase', 'en_vigueur', 'En vigueur', 'unverified', 'Décret n° 2004-1013 fixant les durées de préavis de résiliation du contrat de travail', 'Baremise précise des préavis applicables par secteur d''activité et par catégorie professionnelle à Madagascar.', ARRAY['#Préavis', '#Décret', '#Catégorie professionnelle']::text[], 2, '[{"number":"Article 1","text":"En application de l'' Article 42 du Code du Travail , la durée du préavis pour la catégorie M1 (Ouvriers/Employés) est fixée à 15 jours, et s''élève jusqu''à 3 mois pour la catégorie Cadres (C1 à C3).","references":[{"law_id":"loi-travail-2003","article":"Article 42","label":"Article 42 du Code du Travail"}],"definitions":[]},{"number":"Article 4","text":"Pendant la durée du préavis, le salarié bénéficie de deux jours de liberté par semaine payés à plein tarif pour la recherche d''un nouvel emploi.","references":[],"definitions":[]}]'::jsonb, null, null),
  ('loi-foncier-2008', 'Loi n° 2008-014', 'Loi Ordinaire', 'Droit Foncier', 'fa-map-location-dot', 'en_vigueur', 'En vigueur', 'unverified', 'Loi n° 2008-014 relative au Domaine Privé de l''État et des Collectivités Territoriales', 'Fixe le régime juridique du domaine privé de l''État, abolit la présomption de domanialité et encadre la propriété non titrée.', ARRAY['#Guichet Foncier', '#Certificat Foncier', '#Propriété non titrée']::text[], 2, '[{"number":"Article 2","text":"Sont incluses dans le Domaine Privé non titré de l''État, les terres occupées et exploitées de façon continue et non contestée conformément à l'' Article 34 de la Constitution .","references":[{"law_id":"const-2010","article":"Article 34","label":"Article 34 de la Constitution"}],"definitions":[]},{"number":"Article 15","text":"Le certificat foncier délivré par la Commune atteste des droits de propriété non titrée de l occupant. Voir aussi les détails d application dans l'' Arrêté n° 12450/2021 .","references":[{"law_id":"arrete-foncier-2021","article":"Article 3","label":"Arrêté n° 12450/2021"}],"definitions":[{"term":"Certificat Foncier","definition":"Acte administratif délivré par le guichet foncier communal attestant des droits d occupation et de propriété non titrée sur une parcelle."}]}]'::jsonb, null, null),
  ('arrete-foncier-2021', 'Arrêté n° 12450/2021', 'Arrêté', 'Droit Foncier', 'fa-map-location-dot', 'en_vigueur', 'En vigueur', 'unverified', 'Arrêté n° 12450/2021 fixant la procédure de délivrance des Certificats Fonciers Communaux', 'Détaille la procédure d''instruction sur le terrain par la commission locale de reconnaissance foncière.', ARRAY['#Procédure', '#Commune', '#Bornage', '#Enquête parcellaire']::text[], 2, '[{"number":"Article 1","text":"La demande d''obtention du certificat foncier est déposée auprès du Guichet Foncier de la Commune de situation de l''immeuble.","references":[],"definitions":[]},{"number":"Article 3","text":"La Reconnaissance Locale Parcellaire (RLP) est effectuée publiquement sur le terrain par la Commission en présence des voisins de lieu. En application directe de l'' Article 15 de la Loi n° 2008-014 .","references":[{"law_id":"loi-foncier-2008","article":"Article 15","label":"Article 15 de la Loi n° 2008-014"}],"definitions":[]}]'::jsonb, null, null),
  ('loi-anticorruption-2016', 'Loi n° 2016-021', 'Loi Ordinaire', 'Droit Pénal & Procédure', 'fa-gavel', 'en_vigueur', 'En vigueur', 'unverified', 'Loi n° 2016-021 sur la Lutte contre la Corruption', 'Renforce les incriminations de corruption active/passive, le trafic d''influence et met en place les Pôles Anti-Corruption (PAC).', ARRAY['#Corruption', '#BIANCO', '#PAC', '#Blanchiment']::text[], 2, '[{"number":"Article 2","text":"Est puni d''emprisonnement de 2 à 5 ans et d''une amende le fait pour toute personne sollicitant ou acceptant un avantage indu pour accomplir ou s''abstenir d''accomplir un acte de sa fonction.","references":[],"definitions":[]},{"number":"Article 18","text":"Cet article remplace et abroge l''ancien dispositif pénal de la Loi n° 1962-002 (Ancienne) .","references":[{"law_id":"loi-penal-ancien","article":"Article 100 (Abrogé)","label":"Loi n° 1962-002 (Ancienne)"}],"definitions":[]}]'::jsonb, null, null),
  ('loi-penal-ancien', 'Loi n° 1962-002 (Ancienne)', 'Loi Ordinaire', 'Droit Pénal & Procédure', 'fa-gavel', 'abroge', 'Abrogé / Modifié', 'unverified', 'Loi n° 1962-002 relative à la répression de l''infraction pénal (Ancien Code)', 'Ancien texte pénal répressif partiellement abrogé et remplacé par les lois anticorruption modernes.', ARRAY['#Procédure', '#Ancien texte', '#Abrogé']::text[], 1, '[{"number":"Article 100 (Abrogé)","text":"Anciennes dispositions sur les contraventions. [Cet article a été abrogé et remplacé par la Loi n° 2016-021 sur la Lutte contre la Corruption]","references":[],"definitions":[]}]'::jsonb, 'loi-anticorruption-2016', null),
  ('loi-societes-2003', 'Loi n° 2003-036', 'Loi Ordinaire', 'Droit Commercial & des Affaires', 'fa-chart-line', 'en_vigueur', 'En vigueur', 'unverified', 'Loi n° 2003-036 sur les Sociétés Commerciales et le GIE à Madagascar', 'Régit la création, le fonctionnement et la dissolution des SARL, SA, Sociétés Unipersonnelles et Groupements d''Intérêt Économique.', ARRAY['#Sociétés', '#SARL', '#Capital social', '#Registre du Commerce']::text[], 2, '[{"number":"Article 4","text":"La Société à Responsabilité Limitée (SARL) peut être constituée par une ou plusieurs personnes physiques ou morales. Le capital social est librement fixé par les statuts.","references":[],"definitions":[]},{"number":"Article 28","text":"Toute société commerciale doit s''immatriculer au Registre du Commerce et des Sociétés (RCS) auprès du Tribunal de Commerce compétent.","references":[],"definitions":[]}]'::jsonb, null, null),
  ('loi-environnement-2015', 'Loi n° 2015-003', 'Loi Ordinaire', 'Droit de l''Environnement', 'fa-tree', 'en_vigueur', 'En vigueur', 'unverified', 'Loi n° 2015-003 portant Charte de l''Environnement Malagasy actualisée', 'Établit les principes de développement durable, l''obligation d''Étude d''Impact Environnemental (EIE) et la protection de la biodiversité.', ARRAY['#Environnement', '#EIE', '#Développement durable', '#Forêts']::text[], 2, '[{"number":"Article 3","text":"L''environnement constitue un patrimoine national dont la préservation est d''intérêt général. L''État et les citoyens ont l''obligation de protéger les ressources naturelles uniques de Madagascar.","references":[],"definitions":[]},{"number":"Article 10","text":"Tout projet d''investissement public ou privé susceptible de porter atteinte à l''environnement doit obligatoirement faire l''objet d''une Étude d''Impact Environnemental (EIE) préalable.","references":[],"definitions":[]}]'::jsonb, null, null)
insert into public.lexicon_terms (term, definition) values
  ('Abrogation', 'Suppression définitive de tout ou partie d''un texte juridique par un nouveau texte légal de même valeur ou supérieure.'),
  ('Certificat Foncier', 'Document administratif délivré par le guichet foncier communal constatant le droit de propriété non titrée sur un terrain.'),
  ('Texte Consolidé', 'Texte de loi intégrant dans un document unique l''ensemble de ses modifications et amendements ultérieurs.'),
  ('Préavis', 'Délai légal d''exécution du travail ou de prévenance à respecter lors de la résiliation d''un contrat de travail.'),
  ('Ordonnance', 'Acte pris par le Président de la République dans des domaines réservés normalement à la loi, sous réserve de ratification.'),
  ('Domanialité', 'Régime juridique s''appliquant aux biens meubles et immeubles appartenant à l''État ou aux collectivités locales.'),
  ('Loi Organique', 'Loi votée par le Parlement visant à préciser ou compléter les modalités d''application prévues par la Constitution.'),
  ('Arrêté', 'Décision administrative émanant d''un Ministre, d''un Gouverneur ou d''un Maire précisant les règles d''exécution des lois.')
